diff --git a/source/standalone/switching-response-ok.ts b/source/standalone/switching-response-ok.ts
new file mode 100644
index 0000000..9fd686e
--- /dev/null
+++ b/source/standalone/switching-response-ok.ts
@@ -0,0 +1,24 @@
+export type SwitchingResponseOptions<ResponseType> = {
+	followRedirect: boolean | ((response: ResponseType) => boolean);
+};
+
+export type SwitchingResponseRequest<ResponseType> = {
+	options: SwitchingResponseOptions<ResponseType>;
+};
+
+export type SwitchingResponse = {
+	statusCode: number;
+	request: SwitchingResponseRequest<SwitchingResponse>;
+};
+
+/**
+Like `isResponseOk`, but also accepts `101 Switching Protocols` regardless of the `followRedirect` result.
+*/
+export const isSwitchingResponseOk = <ResponseType extends SwitchingResponse>(response: ResponseType): boolean => {
+	const {statusCode} = response;
+	const {followRedirect} = response.request.options as SwitchingResponseOptions<ResponseType>;
+	const shouldFollow = typeof followRedirect === 'function' ? followRedirect(response) : followRedirect;
+	const limitStatusCode = shouldFollow ? 299 : 399;
+
+	return (statusCode >= 200 && statusCode <= limitStatusCode) || statusCode === 304 || statusCode === 101;
+};
diff --git a/test/switching-response-ok.ts b/test/switching-response-ok.ts
new file mode 100644
index 0000000..598707b
--- /dev/null
+++ b/test/switching-response-ok.ts
@@ -0,0 +1,70 @@
+import test from 'ava';
+import {isSwitchingResponseOk, type SwitchingResponse} from '../source/standalone/switching-response-ok.js';
+
+const createResponse = (statusCode: number, followRedirect: SwitchingResponse['request']['options']['followRedirect']): SwitchingResponse => ({
+	statusCode,
+	request: {options: {followRedirect}},
+});
+
+test('accepts 2xx status codes', t => {
+	for (const followRedirect of [true, false]) {
+		t.true(isSwitchingResponseOk(createResponse(200, followRedirect)));
+		t.true(isSwitchingResponseOk(createResponse(299, followRedirect)));
+	}
+});
+
+test('accepts 3xx only when not following redirects', t => {
+	t.false(isSwitchingResponseOk(createResponse(301, true)));
+	t.false(isSwitchingResponseOk(createResponse(399, true)));
+	t.true(isSwitchingResponseOk(createResponse(301, false)));
+	t.true(isSwitchingResponseOk(createResponse(399, false)));
+});
+
+test('always accepts 304', t => {
+	t.true(isSwitchingResponseOk(createResponse(304, true)));
+	t.true(isSwitchingResponseOk(createResponse(304, false)));
+});
+
+test('always accepts 101 regardless of followRedirect', t => {
+	t.true(isSwitchingResponseOk(createResponse(101, true)));
+	t.true(isSwitchingResponseOk(createResponse(101, false)));
+	t.true(isSwitchingResponseOk(createResponse(101, () => true)));
+	t.true(isSwitchingResponseOk(createResponse(101, () => false)));
+});
+
+test('rejects other status codes', t => {
+	for (const statusCode of [0, 100, 102, 199, 400, 404, 500]) {
+		t.false(isSwitchingResponseOk(createResponse(statusCode, false)));
+		t.false(isSwitchingResponseOk(createResponse(statusCode, true)));
+	}
+});
+
+test('evaluates followRedirect callback with the response', t => {
+	const response = createResponse(302, (received: SwitchingResponse) => {
+		t.is(received, response);
+		return received.statusCode !== 302;
+	});
+
+	t.true(isSwitchingResponseOk(response));
+	t.false(isSwitchingResponseOk(createResponse(302, () => true)));
+	t.plan(3);
+});
+
+test('calls followRedirect callback even for 101', t => {
+	let calls = 0;
+	t.true(isSwitchingResponseOk(createResponse(101, () => {
+		calls++;
+		return true;
+	})));
+	t.is(calls, 1);
+});
+
+test('throws when the followRedirect callback throws', t => {
+	t.throws(() => isSwitchingResponseOk(createResponse(200, () => {
+		throw new Error('boom');
+	})), {message: 'boom'});
+});
+
+test('throws on missing request', t => {
+	t.throws(() => isSwitchingResponseOk({statusCode: 200} as unknown as SwitchingResponse), {instanceOf: TypeError});
+});
